"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["13987"],{62668(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modelo_de_documento.nao_confirmado","status":422,"titulo":"Modelo de documento ainda n\xe3o confirmado"},"descricao":{"codigo":"uniplus.selecao.modelo_de_documento.nao_confirmado","requisitos":[],"oQueAconteceu":["O modelo de documento chega ao processo em tr\xeas passos: o in\xedcio do envio, que devolve uma URL de\\nenvio; o envio do arquivo direto ao armazenamento, sem passar pela API; e a confirma\xe7\xe3o, em que o\\nservidor l\xea o arquivo, confere o conte\xfado e guarda o modelo como imut\xe1vel. O modelo existe, mas\\nest\xe1 no primeiro ou no segundo passo: ainda n\xe3o foi confirmado.","Ao salvar o rascunho, o modelo pendente gera diagn\xf3stico com o ponteiro `/documentosExigidos/exigencias/{i}/modeloId`; a publica\xe7\xe3o recusa a configura\xe7\xe3o enquanto a causa persistir. Ao importar em outro rascunho, envie o arquivo novamente para o novo dono e atualize a cita\xe7\xe3o.","S\xf3 o modelo confirmado tem conte\xfado conferido e pode ser usado. A recusa aparece nas opera\xe7\xf5es seguintes:","- na **consulta do acesso** ao modelo, que n\xe3o entrega um link de leitura para um arquivo que n\xe3o\\n  passou pela confer\xeancia;\\n- na **defini\xe7\xe3o de documentos exigidos**, quando uma exig\xeancia cita o modelo: o modelo precisa\\n  existir neste processo (sen\xe3o a recusa \xe9\\n  [`modelo_nao_encontrado`](/erros/uniplus.selecao.documento_exigido.modelo_nao_encontrado)) e,\\n  al\xe9m disso, estar confirmado. Dentro da exig\xeancia, essa confer\xeancia vem depois das de idade\\n  m\xe1xima de emiss\xe3o e de formatos permitidos."],"comoResolver":["Confirme o envio do modelo e repita a opera\xe7\xe3o. Se o envio ficou pendente al\xe9m do prazo, o registro\\n\xe9 removido pelo sistema e a confirma\xe7\xe3o responde\\n[`nao_encontrado`](/erros/uniplus.selecao.modelo_de_documento.nao_encontrado): inicie um novo envio.\\nSe a confirma\xe7\xe3o recusar por falta do arquivo no armazenamento\\n([`objeto_nao_encontrado`](/erros/uniplus.selecao.modelo_de_documento.objeto_nao_encontrado)),\\nenvie o arquivo \xe0 URL e confirme de novo."],"ondeAparece":["Grava\xe7\xe3o do rascunho do processo seletivo","Consulta do acesso ao modelo de documento","Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modelo de documento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);